'use client';

import { useState } from 'react';
import { motion } from 'framer-motion';
import Link from 'next/link';
import { Navbar } from '@/components/layout/Navbar';
import { Button } from '@/components/ui/Button';
import { useDesignStore } from '@/lib/store';
import { Box, Plus, Trash2, ExternalLink, Clock } from 'lucide-react';

export default function SavedPage() {
  const { savedDesigns, deleteSavedDesign } = useDesignStore();
  const [hoveredId, setHoveredId] = useState<string | null>(null);

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (confirm('Delete this design?')) {
      deleteSavedDesign(id);
    }
  };

  const formatDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    });
  };

  return (
    <div className="min-h-screen bg-[#F7F7F5]">
      <Navbar />
      
      {/* Header */}
      <section className="pt-32 pb-12 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4"
          >
            <div>
              <h1 className="text-4xl lg:text-5xl font-bold text-[#111111] mb-2">
                Saved Designs
              </h1>
              <p className="text-lg text-[#5A5A5F]">
                {savedDesigns.length} {savedDesigns.length === 1 ? 'design' : 'designs'} saved
              </p>
            </div>
            <Link href="/templates">
              <Button>
                <Plus className="w-5 h-5 mr-2" />
                New Design
              </Button>
            </Link>
          </motion.div>
        </div>
      </section>

      {/* Designs Grid */}
      <section className="pb-24 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto">
          {savedDesigns.length === 0 ? (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="text-center py-24"
            >
              <div className="w-24 h-24 mx-auto mb-6 bg-[#F0EFE9] rounded-3xl flex items-center justify-center">
                <Box className="w-12 h-12 text-[#C6A85C]" />
              </div>
              <h2 className="text-2xl font-semibold text-[#111111] mb-3">No saved designs yet</h2>
              <p className="text-[#5A5A5F] mb-8 max-w-md mx-auto">
                Start creating your first event design and it will appear here
              </p>
              <Link href="/templates">
                <Button size="lg">
                  <Plus className="w-5 h-5 mr-2" />
                  Create Your First Design
                </Button>
              </Link>
            </motion.div>
          ) : (
            <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {savedDesigns.map((design, i) => (
                <motion.div
                  key={design.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.05 }}
                  onMouseEnter={() => setHoveredId(design.id)}
                  onMouseLeave={() => setHoveredId(null)}
                >
                  <Link href={`/studio?id=${design.id}`}>
                    <div className="group bg-white rounded-2xl overflow-hidden shadow-md border border-[#E5E5E8] hover:shadow-lg transition-all duration-300">
                      {/* Preview */}
                      <div 
                        className="relative aspect-[4/3] overflow-hidden"
                        style={{ 
                          background: `linear-gradient(135deg, ${design.roomSettings.wallColor} 0%, ${design.roomSettings.floorColor} 100%)` 
                        }}
                      >
                        {/* Overlay on hover */}
                        <div className={`absolute inset-0 bg-black/40 flex items-center justify-center transition-opacity duration-300 ${hoveredId === design.id ? 'opacity-100' : 'opacity-0'}`}>
                          <span className="inline-flex items-center gap-2 px-4 py-2 bg-white rounded-full text-sm font-medium text-[#111111]">
                            <ExternalLink className="w-4 h-4" />
                            Open Design
                          </span>
                        </div>
                        
                        {/* Object count badge */}
                        <div className="absolute top-4 right-4 px-3 py-1 bg-white/90 backdrop-blur-sm rounded-full text-xs font-medium text-[#111111]">
                          {design.objects.length} items
                        </div>
                      </div>
                      
                      {/* Info */}
                      <div className="p-5">
                        <h3 className="text-lg font-semibold text-[#111111] mb-1 truncate">{design.name}</h3>
                        <div className="flex items-center gap-1 text-[#8C8C92] text-sm mb-4">
                          <Clock className="w-4 h-4" />
                          <span>Edited {formatDate(design.updatedAt)}</span>
                        </div>
                        
                        <button
                          onClick={(e) => handleDelete(design.id, e)}
                          className="w-full flex items-center justify-center gap-2 py-2 text-[#8C8C92] hover:text-red-500 hover:bg-red-50 rounded-xl transition-colors text-sm font-medium"
                        >
                          <Trash2 className="w-4 h-4" />
                          Delete
                        </button>
                      </div>
                    </div>
                  </Link>
                </motion.div>
              ))}
            </div>
          )}
        </div>
      </section>
    </div>
  );
}
